( e => {
const { [ 'pt' ]: translations } = {"pt":{"dictionary":{"Copy selected content":"Copiar o conteúdo selecionado","Paste content":"Colar o conteúdo","Paste content as plain text":"Colar o conteúdo como texto sem formatação"}}};
e[ 'pt' ] ||= { dictionary: {}, getPluralForm: null };
e[ 'pt' ].dictionary = Object.assign( e[ 'pt' ].dictionary, translations.dictionary );
if ( translations.getPluralForm ) {
e[ 'pt' ].getPluralForm = translations.getPluralForm;
}
} )( window.CKEDITOR_TRANSLATIONS ||= {} );
